input.command:
S=/private/tmp/claude-501/-Users-serro-Documents-dev-n-agent-experiments-skillplane/ca62123f-e191-43ba-a12e-6d1b29e43d5c/scratchpad; mkdir -p $S/pr47; cd $S/pr47
export GH_CONFIG_DIR=~/.config/gh-other
gh api graphql --paginate -f query='
query($endCursor: String) {
  repository(owner: "21nCo", name: "skillplane") {
    pullRequest(number: 47) {
      headRefOid
      reviewThreads(first: 100, after: $endCursor) {
        nodes { id isResolved isOutdated path line
          comments(first: 50) { nodes { databaseId body author { login } createdAt outdated url originalLine line } pageInfo { hasNextPage endCursor } }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}' > threads.json
python3 - <<'EOF'
import json
txt=open('threads.json').read()
# paginate may concatenate objects
dec=json.JSONDecoder();i=0;objs=[]
while i<len(txt):
  txt2=txt[i:].lstrip()
  if not txt2:break
  o,n=dec.raw_decode(txt2);objs.append(o);i=len(txt)-len(txt2)+n
nodes=[];
for o in objs:
  pr=o['data']['repository']['pullRequest'];print('head',pr['headRefOid'])
  nodes+=pr['reviewThreads']['nodes']
print('total',len(nodes),'unresolved',sum(not n['isResolved'] for n in nodes))
for n in nodes:
  if n['comments']['pageInfo']['hasNextPage']:print('NESTED MORE',n['id'])
json.dump(nodes,open('nodes.json','w'))
for n in nodes:
  if n['isResolved']:continue
  c=n['comments']['nodes']
  print('-----',n['id'],n['path'],n['line'],'outdated' if n['isOutdated'] else '',len(c))
  for x in c: print(' ['+x['author']['login']+']',x['body'][:1500].replace('\n\n','\n'))
EOF

