content.content:
1	import { assertGitSourceLease } from "./git-provenance.js";
2	import type { Pool, PoolClient } from "pg";
3	import { authorize } from "./authorization.js";
4	import { DomainError } from "./errors.js";
5	import type { Principal } from "./principal.js";
6	import { hashIdempotentRequest, validateIdempotencyKey } from "./idempotency.js";
7	import { withDomainTransaction } from "./transactions.js";
8	import { insertPrincipalAudit } from "./mutation-audit.js";
9	import type { SkillService } from "./skills.js";
10	import type { SkillVersionService } from "./skill-versions.js";
11	import {
12	  gitSourceConfig,
13	  PublicGitHubSourceProvider,
14	  type GitSourceConfig,
15	  type GitSourceProvider,
16	} from "./git-source-provider.js";
17	interface Mutation {
18	  principal: Principal;
19	  requestId: string;
20	  fencingEpoch?: number;
21	}
22	interface SourceRow {
23	  id: string;
24	  workspace_id: string;
25	  repository_url: string;
26	  ref: string;
27	  ref_policy: "track" | "pin";
28	  skill_path: string | null;
29	  revision: number;
30	  archived_at: Date | null;
31	  creation_hash: string;
32	  sync_token: string | null;
33	  sync_expires_at: Date | null;
34	  created_at: Date;
35	  updated_at: Date;
36	}
37	export interface GitSource {
38	  id: string;
39	  workspaceId: string;
40	  repositoryUrl: string;
41	  ref: string;
42	  refPolicy: "track" | "pin";
43	  path: string | null;
44	  revision: number;
45	  archivedAt: string | null;
46	  updatedAt: string;
47	}
48	function record(r: SourceRow): GitSource {
49	  return {
50	    id: r.id,
51	    workspaceId: r.workspace_id,
52	    repositoryUrl: r.repository_url,
53	    ref: r.ref,
54	    refPolicy: r.ref_policy,
55	    path: r.skill_path,
56	    revision: r.revision,
57	    archivedAt: r.archived_at?.toISOString() ?? null,
58	    updatedAt: r.updated_at.toISOString(),
59	  };
60	}
61	interface Binding {
62	  skill_path: string;
63	  skill_id: string;
64	  last_commit_sha: string | null;
65	  last_digest: string | null;
66	  last_version_id: string | null;
67	  base_version_id: string | null;
68	  status: string;
69	  current_published_version_id: string | null;
70	  archived_at: Date | null;
71	  slug: string;
72	  name: string;
73	  current_digest: string | null;
74	  visibility: "private" | "public";
75	  disconnected_at: Date | null;
76	}
77	export interface GitPlanEntry {
78	  path: string;
79	  slug: string | null;
80	  digest: string | null;
81	  action: "added" | "changed" | "unchanged" | "missing" | "conflict" | "error";
82	  skillId: string | null;
83	  baseVersionId: string | null;
84	  bindingVersionId: string | null;
85	  message: string | null;
86	}
87	export interface GitApplyResult {
88	  path: string;
89	  status: string;
90	  skillId: string | null;
91	  versionId: string | null;
92	  message: string | null;
93	}
94	interface RunRow {
95	  id: string;
96	  workspace_id: string;
97	  source_id: string;
98	  source_revision: number;
99	  failure_message: string | null;
100	  commit_sha: string;
101	  plan: GitPlanEntry[];
102	  results: GitApplyResult[];
103	  status: "preview" | "partial" | "complete";
104	  created_at: Date;
105	  applied_at: Date | null;
106	}
107	function runRecord(r: RunRow) {
108	  return {
109	    id: r.id,
110	    commitSha: r.commit_sha,
111	    plan: r.plan,
112	    results: r.results,
113	    status: r.status,
114	    failureMessage: r.failure_message,
115	    createdAt: r.created_at.toISOString(),
116	    appliedAt: r.applied_at?.toISOString() ?? null,
117	  };
118	}
119	export class GitSourceService {
120	  constructor(
121	    private readonly pool: Pool,
122	    private readonly skills: SkillService,
123	    private readonly versions: SkillVersionService,
124	    private readonly provider: GitSourceProvider = new PublicGitHubSourceProvider(),
125	  ) {}
126	  private transaction<T>(m: Mutation, fn: (client: PoolClient) => Promise<T>) {
127	    return withDomainTransaction(this.pool, m.requestId, ({ client }) => fn(client), {
128	      fencingEpoch: m.fencingEpoch,
129	    });
130	  }
131	  private async audit(
132	    c: PoolClient,
133	    m: Mutation,
134	    id: string,
135	    event: string,
136	    metadata: Record<string, unknown> = {},
137	  ) {
138	    await insertPrincipalAudit(c, m.principal, {
139	      eventType: `skill_source.${event}`,
140	      action: "workspace:update",
141	      requestId: m.requestId,
142	      resourceType: "skill_source",
143	      resourceId: id,
144	      metadata,
145	    });
146	  }
147	  private async row(
148	    p: Principal,
149	    id: string,
150	    c: Pool | PoolClient = this.pool,
151	    lock = false,
152	  ) {
153	    authorize(p, "skills:read");
154	    const r = await c.query<SourceRow>(
155	      `SELECT * FROM skill_sources WHERE workspace_id=$1 AND id=$2 ${lock ? "FOR UPDATE" : ""}`,
156	      [p.workspaceId, id],
157	    );
158	    if (!r.rows[0]) throw new DomainError("NOT_FOUND", "Source was not found", 404);
159	    return r.rows[0];
160	  }
161	  async list(p: Principal, cursor: string | null = null) {
162	    authorize(p, "skills:read");
163	    if (cursor && cursor.length > 200)
164	      throw new DomainError("VALIDATION_FAILED", "Invalid source cursor", 400);
165	    const r = await this.pool.query<SourceRow>(
