368	  async preview(m: Mutation & { sourceId: string }) {
369	    authorize(m.principal, "workspace:update");
370	    const source = record(await this.row(m.principal, m.sourceId));
371	    if (source.archivedAt)
372	      throw new DomainError("CONFLICT", "Restore the source before syncing", 409);
373	    const snapshot = await this.provider.snapshot(this.config(source)),
374	      bindings = await this.bindings(m.principal, source.id);
375	    const catalog = await this.pool.query<{ slug: string; id: string }>(
376	      "SELECT slug,id FROM skills WHERE workspace_id=$1",
377	      [m.principal.workspaceId],
378	    );
379	    const plan: GitPlanEntry[] = [];
380	    const seen = new Set<string>(),
381	      slugs = new Set<string>();
382	    for (const item of snapshot.skills) {
383	      seen.add(item.path);
384	      const binding = bindings.find((b) => b.skill_path === item.path),
385	        base = {
386	          path: item.path,
387	          slug: item.bundle?.skill.slug ?? null,
388	          digest: item.bundle?.digest ?? null,
389	          skillId: binding?.skill_id ?? null,
390	          baseVersionId: binding?.current_published_version_id ?? null,
391	          bindingVersionId: binding?.last_version_id ?? null,
392	        };
393	      if (!item.bundle) {
394	        plan.push({ ...base, action: "error", message: item.error ?? "Invalid skill" });
395	        continue;
396	      }
397	      const slug = item.bundle.skill.slug,
398	        collision = slugs.has(slug);
399	      slugs.add(slug);
400	      if (
401	        collision ||
402	        (!binding && catalog.rows.some((s) => s.slug === slug)) ||
403	        (binding &&
404	          (binding.slug !== slug ||
405	            binding.archived_at ||
406	            (binding.current_published_version_id !== binding.base_version_id &&
407	              binding.current_published_version_id !== binding.last_version_id)))
408	      ) {
409	        plan.push({
410	          ...base,
411	          action: "conflict",
412	          message:
413	            "Slug conflict, archived skill, or manual changes require explicit resolution",
414	        });
415	        continue;
416	      }
417	      // If a pending imported version was rejected, do not silently call it synced.
418	      const last = binding?.last_version_id
