420	            "SELECT status FROM skill_versions WHERE workspace_id=$1 AND id=$2",
421	            [m.principal.workspaceId, binding.last_version_id],
422	          )
423	        : null;
424	      if (
425	        binding?.last_digest === item.bundle.digest &&
426	        last?.rows[0]?.status === "rejected"
427	      ) {
428	        plan.push({
429	          ...base,
430	          action: "conflict",
431	          message: "The last imported candidate was rejected",
432	        });
433	        continue;
434	      }
435	      let preparedDigest: string;
436	      try {
437	        preparedDigest = (
438	          await this.skills.prepareGitBundle(
439	            item.bundle,
440	            m.principal,
441	            binding?.visibility ?? "private",
442	          )
443	        ).digest;
444	      } catch {
445	        plan.push({
446	          ...base,
447	          action: "error",
448	          message: "Skill composition could not be resolved",
449	        });
450	        continue;
451	      }
452	      plan.push({
453	        ...base,
454	        action: binding
455	          ? binding.last_digest === item.bundle.digest ||
456	            binding.current_digest === preparedDigest
457	            ? "unchanged"
458	            : "changed"
459	          : "added",
460	        message: null,
461	      });
462	    }
463	    for (const binding of bindings)
464	      if (!seen.has(binding.skill_path))
465	        plan.push({
466	          path: binding.skill_path,
467	          slug: binding.slug,
468	          digest: binding.last_digest,
469	          skillId: binding.skill_id,
470	          baseVersionId: binding.current_published_version_id,
471	          bindingVersionId: binding.last_version_id,
472	          action: "missing",
473	          message: "Source path is missing or renamed; the existing skill is preserved",
474	        });
475	    return this.transaction(m, async (c) => {
476	      const current = await this.row(m.principal, source.id, c, true);
477	      if (
478	        current.revision !== source.revision ||
479	        current.archived_at ||
480	        (current.sync_expires_at && current.sync_expires_at > new Date())
481	      )
482	        throw new DomainError(
483	          "CONFLICT",
484	          "Source changed during preview; preview again",
485	          409,
486	        );
487	      const id = `source-run:${crypto.randomUUID()}`;
488	      const r = await c.query<RunRow>(
489	        "INSERT INTO skill_source_runs(id,workspace_id,source_id,source_revision,commit_sha,plan) VALUES($1,$2,$3,$4,$5,$6) RETURNING *",
490	        [
491	          id,
492	          m.principal.workspaceId,
493	          source.id,
494	          source.revision,
495	          snapshot.commitSha,
