1	import { parse } from "yaml";
2	import {
3	  canonicalizeBundleFiles,
4	  normalizeBundlePath,
5	  skillJsonSchema,
6	  type CanonicalBundle,
7	} from "@skillplane/storage";
8	import { DomainError } from "./errors.js";
9	export interface GitSourceConfig {
10	  repositoryUrl: string;
11	  ref: string;
12	  refPolicy: "track" | "pin";
13	  path: string | null;
14	}
15	export interface GitDiscoveredSkill {
16	  path: string;
17	  bundle: CanonicalBundle | null;
18	  error: string | null;
19	}
20	export interface GitSnapshot {
21	  commitSha: string;
22	  skills: GitDiscoveredSkill[];
23	}
24	export interface GitSourceProvider {
25	  snapshot(config: GitSourceConfig, commitSha?: string): Promise<GitSnapshot>;
26	}
27	class SnapshotLimitError extends DomainError {
28	  constructor(message: string) {
29	    super("VALIDATION_FAILED", message, 400);
30	  }
31	}
32	function invalid(message: string): never {
33	  throw new DomainError("VALIDATION_FAILED", message, 400);
34	}
35	export function gitSourceConfig(input: Record<string, unknown>): GitSourceConfig {
36	  if (typeof input.repositoryUrl !== "string")
37	    invalid("A public GitHub repository URL is required");
38	  let url: URL;
39	  try {
40	    url = new URL(input.repositoryUrl);
41	  } catch {
42	    invalid("Invalid repository URL");
43	  }
44	  const match =
45	    /^\/([A-Za-z0-9][A-Za-z0-9-]{0,38})\/([A-Za-z0-9_.-]{1,100}?)(?:\.git)?\/?$/.exec(
46	      url.pathname,
47	    );
48	  if (
49	    url.protocol !== "https:" ||
50	    url.hostname !== "github.com" ||
51	    url.port ||
52	    url.username ||
53	    url.password ||
54	    url.search ||
55	    url.hash ||
56	    !match ||
57	    match[2] === "." ||
58	    match[2] === ".."
59	  )
60	    invalid("Use an HTTPS github.com owner/repository URL");
61	  const ref = input.ref ?? "HEAD",
62	    refPolicy = input.refPolicy ?? "track",
63	    path = input.path ?? null;
64	  if (
65	    typeof ref !== "string" ||
66	    !ref ||
67	    ref.length > 200 ||
68	    // eslint-disable-next-line no-control-regex -- reject control characters in untrusted refs
69	    /[\x00-\x20\\?#]/u.test(ref)
70	  )
71	    invalid("A valid branch, tag, or commit is required");
72	  if (refPolicy !== "pin" && refPolicy !== "track")
73	    invalid("Ref policy must be track or pin");
74	  if (refPolicy === "pin" && !/^[a-f0-9]{40}$/i.test(ref))
75	    invalid("Pinned sources require a full commit SHA");
76	  if (path !== null && (typeof path !== "string" || !safePath(path)))
77	    invalid("Use a safe repository-relative SKILL.md path or skill directory");
78	  return {
79	    repositoryUrl: `https://github.com/${match[1] ?? ""}/${match[2] ?? ""}`,
80	    ref,
81	    refPolicy,
82	    path:
83	      path === "SKILL.md"
84	        ? ""
85	        : typeof path === "string" && path.endsWith("/SKILL.md")
86	          ? path.slice(0, -"/SKILL.md".length)
87	          : path,
88	  };
89	}
90	function safePath(path: string) {
91	  return (
92	    path === "" ||
93	    (path.length <= 240 &&
94	      // eslint-disable-next-line no-control-regex -- reject control characters in untrusted paths
95	      !/[\\\x00-\x1f]/u.test(path) &&
96	      !path.startsWith("/") &&
97	      !/^[A-Za-z]:/.test(path) &&
98	      path.split("/").every((s) => s && s !== "." && s !== ".." && s !== "~"))
99	  );
100	}
101	function object(value: unknown): Record<string, unknown> {
102	  if (!value || typeof value !== "object" || Array.isArray(value))
103	    invalid("GitHub returned invalid data");
104	  return value as Record<string, unknown>;
105	}
106	function text(value: unknown): string {
107	  if (typeof value !== "string") invalid("GitHub returned invalid data");
108	  return value;
109	}
110	interface TreeEntry {
111	  path: string;
112	  mode: string;
113	  type: string;
114	  sha: string;
115	  size: number;
116	}
117	const MAX_SNAPSHOT_BYTES = 20 * 1024 * 1024,
118	  MAX_BLOB_BYTES = 5 * 1024 * 1024,
119	  MAX_REQUESTS = 200;
120	export class PublicGitHubSourceProvider implements GitSourceProvider {
121	  constructor(private readonly fetcher: typeof fetch = globalThis.fetch) {}
122	  async snapshot(input: GitSourceConfig, pinned?: string): Promise<GitSnapshot> {
123	    const config = gitSourceConfig({ ...input });
124	    if (pinned && !/^[a-f0-9]{40}$/i.test(pinned)) invalid("Invalid preview commit");
125	    const repository = config.repositoryUrl.slice("https://github.com/".length);
126	    let requests = 0,
127	      totalBytes = 0;
128	    const deadline = Date.now() + 90000;
129	    const read = async (path: string, maxBytes: number) => {
130	      const remaining = deadline - Date.now();
131	      if (remaining <= 0)
132	        throw new DomainError("SERVICE_UNAVAILABLE", "Git source fetch timed out", 503);
133	      if (++requests > MAX_REQUESTS)
134	        throw new SnapshotLimitError(
135	          "Source exceeds the 200 request import limit; reduce its skill/file scope",
136	        );
137	      let response: Response;
138	      try {
139	        response = await this.fetcher(
140	          `https://api.github.com/repos/${repository}/${path}`,
141	          {
142	            headers: {
143	              accept: "application/vnd.github+json",
144	              "x-github-api-version": "2026-03-10",
145	              "user-agent": "Skillplane-public-source-import",
