      "private",
    );
    expect((await versions.get({ skillId, versionId, principal: owner })).source).toBe(
      "import",
    );
    expect(await sources.provenance(owner, versionId)).toMatchObject({
      commit_sha: "a".repeat(40),
      skill_path: "skills/review",
    });
    await expect(
