input.command:
cd "/Users/serro/Documents/dev/n/agent/experiments/skillplane-ski-12/app/src/routes/(app)/[workspaceSlug]/sources" && python3 - <<'EOF'
p='+page.svelte'; s=open(p).read()
def rep(old,new,count=1):
  global s
  assert s.count(old)==count,(old,s.count(old))
  s=s.replace(old,new)
rep('''  let creationKey = crypto.randomUUID();
  function current(id: string) {
    return workspace?.id === id;
  }''','''  // Each workspace keeps its creation key until a confirmed save or an explicit
  // new source, so re-submitting an ambiguous create after navigation replays it.
  const creationKeys = new Map<string, string>();
  function creationKey(id: string) {
    const key = creationKeys.get(id) ?? crypto.randomUUID();
    creationKeys.set(id, key);
    return key;
  }
  // Every workspace visit starts a new generation, so requests from an earlier
  // visit to the same workspace cannot update or unlock the current one.
  let generation = 0;
  function current(id: string, g: number) {
    return workspace?.id === id && generation === g;
  }''')
n=s.count("    const id = workspace.id;\n")
s=s.replace("    const id = workspace.id;\n","    const id = workspace.id,\n      g = generation;\n")
s=s.replace("      const id = workspace.id;\n","      const id = workspace.id,\n        g = generation;\n")
s=s.replace("    const w = workspace.id,\n","    const w = workspace.id,\n      g = generation,\n")
s=s.replace("current(id)","current(id, g)").replace("current(w)","current(w, g)")
rep('''      creationKey,
    );
    if (!current(id, g)) return;
    creationKey = crypto.randomUUID();''','''      creationKey(id),
    );
    creationKeys.delete(id);
    if (!current(id, g)) return;''')
rep('''  async function bind() {
    if (!workspace || !selected) return;
    await sourceRequest(
      workspace.id,
      `/${encodeURIComponent(selected.source.id)}/bindings`,
      "POST",
      { path: bindPath, skillId: bindSkillId },
    );
    await detail(selected.source);
  }''','''  async function bind() {
    if (!workspace || !selected) return;
    const w = workspace.id,
      g = generation,
      s = selected.source;
    await sourceRequest(w, `/${encodeURIComponent(s.id)}/bindings`, "POST", {
      path: bindPath,
      skillId: bindSkillId,
    });
    if (current(w, g)) await detail(s);
  }''')
rep('''      loaded = workspace.id;
''','''      loaded = workspace.id;
      generation += 1;
''')
rep('''      available = [];
      creationKey = crypto.randomUUID();
''','''      available = [];
''')
rep('''        singlePath = false;
        creationKey = crypto.randomUUID();''','''        singlePath = false;
        if (workspace) creationKeys.delete(workspace.id);''')
open(p,'w').write(s)
print(n)
EOF
grep -n "generation\|creationKey\|current(" +page.svelte

